/*
 * Modified by Actuna Sp. z o.o.:
 *   E-01: shared deploy lock (moved from api/flows.js); holdUntil() keeps the lock
 *   until the start of the flows completes (R-43)
 *   P-01: limit of holding the lock after the section (deploy.startTimeout) and a
 *   warning when the lock is held for long
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

/**
 * The deploy lock: the single lock for operations that change the running
 * flows. Deployments through the Admin API (`POST /flows`, `/flow`), changes
 * of the flows run state (`POST /flows/state`) and project switches run under
 * this lock; a second operation waits until the first one completes.
 *
 * The lock is taken only where an operation enters the runtime (runtime api,
 * project switch) - never in `flows/index.js` - and is not re-entrant: code
 * running under the lock must not call another entry point that takes it.
 *
 * The start of the new flows runs asynchronously to the result of a
 * deployment (the HTTP response does not wait for it). `flows.setFlows`
 * registers the start with `holdUntil()`, so the lock is held until the start
 * completes (contract E-01 step 8, R-43) while the result is returned as before.
 *
 * Safeguard (P-01): a start can take long (for example installing the modules
 * of a function node). With a limit (`deploy.startTimeout`) the lock is
 * released at the latest when the limit has passed - with a warning, the start
 * goes on in the background. Without a limit the lock is kept until the start
 * completes and a warning is logged once it has been held for long (60 s).
 * @module
 */

const Mutex = require('async-mutex').Mutex;
const log = require("@node-red/util").log;
const mutex = new Mutex();

// How long a held promise without a limit can keep the lock before a warning
const DEFAULT_WARN_AFTER = 60000;

// The promises registered by holdUntil() in the running section, or null
// outside a section
let held = null;

/**
 * Runs `fn` under the deploy lock. The returned promise settles when the
 * promise returned by `fn` settles (or if `fn` throws); the lock is released
 * then, or - if `fn` registered promises with `holdUntil()` - when all of
 * them have settled (resolved or rejected).
 * @param {Function} fn - the function to run; may return a promise
 * @return {Promise} - resolves/rejects with the result of `fn`
 */
async function runExclusive(fn) {
    const release = await mutex.acquire();
    const sectionHeld = held = [];
    const finish = function() {
        held = null;
        if (sectionHeld.length === 0) {
            release();
        } else {
            Promise.all(sectionHeld.map(waitForHeld)).then(function() { release() });
        }
    };
    let result;
    try {
        result = await fn();
    } catch (err) {
        finish();
        throw err;
    }
    finish();
    return result;
}

// Resolves when the held entry no longer keeps the lock: when its promise has
// settled or - with a limit - when the limit has passed (with a warning)
function waitForHeld(entry) {
    if (!entry.deadline) {
        return entry.settled;
    }
    return new Promise(function(resolve) {
        const timer = setTimeout(function() {
            if (!entry.done) {
                log.warn(log._("deploy.lock-released-after-timeout", {timeout: entry.limit}));
            }
            resolve();
        }, Math.max(0, entry.deadline - Date.now()));
        entry.settled.then(function() {
            clearTimeout(timer);
            resolve();
        });
    });
}

/**
 * Keeps the deploy lock after the running section returns, until `promise`
 * settles. Outside a section it does nothing (for example the start of the
 * flows when the runtime starts).
 * @param {Promise} promise
 * @param {Object} [options]
 * @param {number} [options.limit] - with a positive value (ms), the lock is kept at
 *     most until this time after the call has passed; then it is released with a
 *     warning while the promise is still pending (P-01, `deploy.startTimeout`)
 * @param {number} [options.warnAfter=60000] - without a limit: log a warning when
 *     the promise has not settled after this time (ms); the lock is kept
 */
function holdUntil(promise, options) {
    if (!held) {
        return;
    }
    options = options || {};
    const entry = { done: false };
    entry.settled = Promise.resolve(promise).then(function() { entry.done = true }, function() { entry.done = true });
    if (options.limit > 0) {
        entry.limit = options.limit;
        entry.deadline = Date.now() + options.limit;
    } else {
        const warnAfter = options.warnAfter > 0 ? options.warnAfter : DEFAULT_WARN_AFTER;
        const timer = setTimeout(function() {
            if (!entry.done) {
                log.warn(log._("deploy.lock-held-long", {seconds: Math.round(warnAfter / 1000)}));
            }
        }, warnAfter);
        // Do not keep the process alive for the warning only
        if (timer.unref) {
            timer.unref();
        }
        entry.settled.then(function() { clearTimeout(timer) });
    }
    held.push(entry);
}

/**
 * Whether the deploy lock is currently held.
 * @return {boolean}
 */
function isLocked() {
    return mutex.isLocked();
}

module.exports = {
    runExclusive,
    holdUntil,
    isLocked
};
